/**
 * Calculates the total price of the items in the cart.
 *
 * @param {Array<Item>} items - the cart items to total.
 * @param {number} taxRate - the tax rate to apply, as a decimal.
 * @returns {number} the total price including tax.
 */
function cartTotal(items, taxRate) {
  const subtotal = items.reduce((sum, item) => sum + item.price, 0);
  return subtotal * (1 + taxRate);
}

/**
 * Parse the date.
 *
 * @param {string} input - the ISO date string to parse.
 * @returns {Date} the parsed date.
 */
function parseDate(input) {
  return new Date(input);
}

/**
 * Adds two numbers together and returns their sum.
 *
 * @param {number} a - the first addend.
 * @param {number} c - the second addend.
 * @returns {number} the sum of the two addends.
 */
function add(a, b) {
  return a + b;
}

/**
 * Counts the number of active users in the list.
 *
 * @param {Array<User>} users - the users to inspect.
 */
function activeCount(users) {
  return users.filter((u) => u.active).length;
}

/**
 * Creates a new user record from the supplied options.
 *
 * @param {Object} options - the user options.
 * @returns {User} the newly created user.
 */
function createUser({ name, age }) {
  return { name, age, id: nextId() };
}

/**
 * Draws a point at the given coordinates.
 *
 * @param {number} x - the horizontal coordinate.
 */
function draw({ x, y }) {
  plot(x, y);
}

/**
 * Logs a message to the console with a timestamp prefix.
 *
 * @param {string} message - the message to log.
 */
function log(message) {
  console.log(`[${new Date().toISOString()}] ${message}`);
}

/**
 * Formats a duration in seconds as a human-readable string.
 *
 * @param {number} seconds - the duration in seconds.
 * @param {boolean} short - whether to use the short form.
 * @returns {string} the formatted duration.
 */
function formatDuration(seconds, short) {
  const minutes = Math.floor(seconds / 60);
  return short ? `${minutes}m` : `${minutes} minute(s)`;
}

/**
 * Get user.
 *
 * @param {string} id - the user id.
 */
function getUser(id) {
  return db.users.find((u) => u.id === id);
}
